-- Experiment.testKey (SLA-806): the test, i.e. one hypothesis, that an
-- experiment is an attempt of. Re-creating a failed run under the same key
-- groups the attempts, and their spend, in slashloop itself. A real column,
-- not dataJson, so "every attempt of this test" is an index seek.
-- Legacy rows stay NULL.
--
-- Mirrors the field and @@index in prisma/schema.prisma (and
-- prisma/schema.sqlite.prisma, generated by src/scripts/sync-sqlite-schema.ts).
--
-- Apply with: wrangler d1 migrations apply slashloop --remote
ALTER TABLE "Experiment" ADD COLUMN "testKey" TEXT;
CREATE INDEX IF NOT EXISTS "Experiment_workspaceId_testKey_createdAt_idx"
  ON "Experiment"("workspaceId", "testKey", "createdAt");
